type Listener<D> = (data: D) => void

export class TypedEventEmitter<EventMap extends Record<string, any>> {
  private events: { [K in keyof EventMap]?: Listener<EventMap[K]>[] } = {}

  on<K extends keyof EventMap>(event: K, listener: Listener<EventMap[K]>): () => void {
    if (!this.events[event]) this.events[event] = []
    this.events[event]!.push(listener)
    return () => {
      const handlers = this.events[event]
      if (!handlers) return
      const index = handlers.indexOf(listener)
      if (index !== -1) handlers.splice(index, 1)
    }
  }

  emit<K extends keyof EventMap>(event: K, data: EventMap[K]): void {
    const handlers = this.events[event] || []
    for (const h of handlers) h(data)
  }
}

import { TypedEventEmitter } from "./events"

interface AppEvents {
  data: string
  error: Error
}

const emitter = new TypedEventEmitter<AppEvents>()

const unsubscribe = emitter.on("data", (chunk) => console.log("Received:", chunk))
emitter.emit("data", "hello world")
unsubscribe()
